// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetDelivery Get a delivery by ID
	// (GET /deliveries/{id})
	GetDelivery(ctx context.Context, request GetDeliveryRequestObject) (GetDeliveryResponseObject, error)
	// RetryDelivery Retry a delivery
	// (POST /deliveries/{id}/retry)
	RetryDelivery(ctx context.Context, request RetryDeliveryRequestObject) (RetryDeliveryResponseObject, error)
	// GetAllEndpoints List endpoints
	// (GET /endpoints)
	GetAllEndpoints(ctx context.Context, request GetAllEndpointsRequestObject) (GetAllEndpointsResponseObject, error)
	// RegisterEndpoint Register a webhook endpoint
	// (POST /endpoints)
	RegisterEndpoint(ctx context.Context, request RegisterEndpointRequestObject) (RegisterEndpointResponseObject, error)
	// DeleteEndpoint Delete an endpoint
	// (DELETE /endpoints/{id})
	DeleteEndpoint(ctx context.Context, request DeleteEndpointRequestObject) (DeleteEndpointResponseObject, error)
	// GetEndpoint Get an endpoint by ID
	// (GET /endpoints/{id})
	GetEndpoint(ctx context.Context, request GetEndpointRequestObject) (GetEndpointResponseObject, error)
	// UpdateEndpoint Update an endpoint
	// (PATCH /endpoints/{id})
	UpdateEndpoint(ctx context.Context, request UpdateEndpointRequestObject) (UpdateEndpointResponseObject, error)
	// GetAllSubscriptions List an endpoint's subscriptions
	// (GET /endpoints/{id}/subscriptions)
	GetAllSubscriptions(ctx context.Context, request GetAllSubscriptionsRequestObject) (GetAllSubscriptionsResponseObject, error)
	// Subscribe Subscribe an endpoint to event types
	// (POST /endpoints/{id}/subscriptions)
	Subscribe(ctx context.Context, request SubscribeRequestObject) (SubscribeResponseObject, error)
	// PublishEvent Publish an event
	// (POST /events)
	PublishEvent(ctx context.Context, request PublishEventRequestObject) (PublishEventResponseObject, error)
	// GetEvent Get an event by ID
	// (GET /events/{id})
	GetEvent(ctx context.Context, request GetEventRequestObject) (GetEventResponseObject, error)
	// GetEventDeliveries List an event's deliveries
	// (GET /events/{id}/deliveries)
	GetEventDeliveries(ctx context.Context, request GetEventDeliveriesRequestObject) (GetEventDeliveriesResponseObject, error)
	// DeleteSubscription Delete a subscription
	// (DELETE /subscriptions/{id})
	DeleteSubscription(ctx context.Context, request DeleteSubscriptionRequestObject) (DeleteSubscriptionResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

